import sys
from math import isqrt

def sieve(limit):
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, isqrt(limit) + 1):
        if is_prime[i]:
            for j in range(i*i, limit + 1, i):
                is_prime[j] = False
    return is_prime

MAX_N = 10**6
is_prime = sieve(MAX_N)

primes = [i for i, p in enumerate(is_prime) if p]
prime_set = set(primes)

squares_of_primes = []
for p in primes:
    sq = p * p
    if sq >= MAX_N:
        break
    squares_of_primes.append(sq)

cubes_of_primes = []
for p in primes:
    cb = p * p * p
    if cb >= MAX_N:
        break
    cubes_of_primes.append(cb)

cube_to_p = {p*p*p: p for p in primes if p*p*p < MAX_N}

def solve():
    input_data = sys.stdin.read().split()
    nums = [int(x) for x in input_data]

    results = []
    for n in nums:
        if n == 0:
            break

        found = False
        ans = (0, 0, 0)

        for cb in cubes_of_primes:
            if cb >= n:
                break
            remainder_after_cube = n - cb
            p3 = cube_to_p[cb]

            for sq in squares_of_primes:
                if sq >= remainder_after_cube:
                    break
                remainder_after_sq = remainder_after_cube - sq

                if remainder_after_sq > 1 and is_prime[remainder_after_sq]:
                    p1 = remainder_after_sq
                    p2 = int(isqrt(sq))
                    ans = (p1, p2, p3)
                    found = True
                    break

            if found:
                break

        results.append(f"{ans[0]} {ans[1]} {ans[2]}")

    for res in results:
        print(res)

if __name__ == "__main__":
    solve()
